package vn.luma.web;

import java.security.Principal;
import java.util.*;
import jakarta.validation.Valid;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;
import vn.luma.business.*;

@Controller
@RequestMapping("/quan-tri")
public class CauHinhSanPhamController {
    private final CauHinhSanPhamService service;private final QuanLySanPhamService products;
    public CauHinhSanPhamController(CauHinhSanPhamService service,QuanLySanPhamService products){this.service=service;this.products=products;}
    private void danhMuc(Principal u,Model m){m.addAttribute("danhMuc",products.danhMuc(u.getName(),"phan-loai"));m.addAttribute("thuongHieu",products.danhMuc(u.getName(),"thuong-hieu"));}
    @GetMapping("/dong-san-pham") public String dong(@RequestParam(defaultValue="0") long hang,@RequestParam(defaultValue="1") int trang,Principal u,Model m){m.addAttribute("dongSanPham",service.dong(u.getName(),hang,trang));m.addAttribute("hang",hang);m.addAttribute("trang",trang);danhMuc(u,m);return "quan-tri/dong-san-pham";}
    @GetMapping({"/dong-san-pham/moi","/dong-san-pham/{id}"}) public String suaDong(@PathVariable(required=false) Long id,Principal u,Model m){danhMuc(u,m);m.addAttribute("maDong",id);if(!m.containsAttribute("form")){if(id==null)m.addAttribute("form",new DongSanPhamYeuCau(0,"",""));else{var r=service.dong(u.getName(),id);m.addAttribute("form",new DongSanPhamYeuCau(number(r,"MaThuongHieu"),(String)r.get("TenDongSanPham"),(String)r.get("DuongDan")));}}return "quan-tri/dong-san-pham-form";}
    @PostMapping({"/dong-san-pham/moi","/dong-san-pham/{id}"}) public String luuDong(@PathVariable(required=false) Long id,@Valid @ModelAttribute("form") DongSanPhamYeuCau f,BindingResult errors,Principal u,Model m,RedirectAttributes flash){if(!errors.hasErrors())try{long saved=service.luuDong(u.getName(),id,f);flash.addFlashAttribute("thongBao","Đã lưu dòng sản phẩm.");return "redirect:/quan-tri/dong-san-pham/"+saved;}catch(IllegalArgumentException ex){m.addAttribute("loi",ex.getMessage());}return suaDong(id,u,m);}
    @PostMapping("/dong-san-pham/{id}/xoa") public String xoaDong(@PathVariable long id,Principal u,RedirectAttributes flash){try{service.xoaDong(u.getName(),id);flash.addFlashAttribute("thongBao","Đã xóa dòng chưa được model sử dụng.");}catch(IllegalArgumentException ex){flash.addFlashAttribute("loi",ex.getMessage());}return "redirect:/quan-tri/dong-san-pham";}
    @PostMapping("/model/{id}/dong") public String ganDong(@PathVariable long id,@RequestParam(required=false) Long maDong,Principal u,RedirectAttributes flash){try{service.ganDong(u.getName(),id,maDong==null||maDong==0?null:maDong);flash.addFlashAttribute("thongBao","Đã cập nhật dòng của model.");}catch(IllegalArgumentException ex){flash.addFlashAttribute("loi",ex.getMessage());}return "redirect:/quan-tri/model/"+id;}
    @GetMapping("/thuoc-tinh") public String thuocTinh(@RequestParam(defaultValue="0") long loai,@RequestParam(defaultValue="1") int trang,Principal u,Model m){m.addAttribute("thuocTinh",service.thuocTinh(u.getName(),loai,trang));m.addAttribute("loai",loai);m.addAttribute("trang",trang);danhMuc(u,m);return "quan-tri/thuoc-tinh";}
    @GetMapping({"/thuoc-tinh/moi","/thuoc-tinh/{id}"}) public String suaThuocTinh(@PathVariable(required=false) Long id,Principal u,Model m){danhMuc(u,m);m.addAttribute("maThuocTinh",id);if(!m.containsAttribute("form")){if(id==null)m.addAttribute("form",new ThuocTinhYeuCau(0,"","","CHU","",false,0));else{var r=service.thuocTinh(u.getName(),id);m.addAttribute("form",new ThuocTinhYeuCau(number(r,"MaPhanLoai"),(String)r.get("KyHieu"),(String)r.get("TenThuocTinh"),(String)r.get("KieuDuLieu"),(String)r.get("DonVi"),(Boolean)r.get("ChoPhepLoc"),((Number)r.get("ThuTu")).intValue()));}}return "quan-tri/thuoc-tinh-form";}
    @PostMapping({"/thuoc-tinh/moi","/thuoc-tinh/{id}"}) public String luuThuocTinh(@PathVariable(required=false) Long id,@Valid @ModelAttribute("form") ThuocTinhYeuCau f,BindingResult errors,Principal u,Model m,RedirectAttributes flash){if(!errors.hasErrors())try{long saved=service.luuThuocTinh(u.getName(),id,f);flash.addFlashAttribute("thongBao","Đã lưu thuộc tính danh mục.");return "redirect:/quan-tri/thuoc-tinh/"+saved;}catch(IllegalArgumentException ex){m.addAttribute("loi",ex.getMessage());}return suaThuocTinh(id,u,m);}
    @PostMapping("/thuoc-tinh/{id}/xoa") public String xoaThuocTinh(@PathVariable long id,Principal u,RedirectAttributes flash){try{service.xoaThuocTinh(u.getName(),id);flash.addFlashAttribute("thongBao","Đã xóa thuộc tính chưa gán giá trị.");}catch(IllegalArgumentException ex){flash.addFlashAttribute("loi",ex.getMessage());}return "redirect:/quan-tri/thuoc-tinh";}
    private void nguCanh(Principal u,long model,long sku,Model m){m.addAttribute("modelSp",products.model(u.getName(),model));m.addAttribute("sku",products.sku(u.getName(),sku));m.addAttribute("maModel",model);m.addAttribute("maSku",sku);}
    @GetMapping("/model/{model}/sku/{sku}/thuoc-tinh") public String giaTri(@PathVariable long model,@PathVariable long sku,Principal u,Model m){m.addAttribute("thuocTinh",service.giaTri(u.getName(),model,sku));nguCanh(u,model,sku,m);return "quan-tri/gia-tri-thuoc-tinh";}
    @GetMapping("/model/{model}/sku/{sku}/thuoc-tinh/{attribute}") public String suaGiaTri(@PathVariable long model,@PathVariable long sku,@PathVariable long attribute,Principal u,Model m){var a=service.giaTri(u.getName(),model,sku,attribute);nguCanh(u,model,sku,m);m.addAttribute("thuocTinh",a);if(!m.containsAttribute("form"))m.addAttribute("form",new GiaTriThuocTinhYeuCau(Objects.toString(a.get("gia_tri_form"),"")));return "quan-tri/gia-tri-thuoc-tinh-form";}
    @PostMapping("/model/{model}/sku/{sku}/thuoc-tinh/{attribute}") public String luuGiaTri(@PathVariable long model,@PathVariable long sku,@PathVariable long attribute,@Valid @ModelAttribute("form") GiaTriThuocTinhYeuCau f,BindingResult errors,Principal u,Model m,RedirectAttributes flash){if(!errors.hasErrors())try{service.luuGiaTri(u.getName(),model,sku,attribute,f);flash.addFlashAttribute("thongBao","Đã lưu thông số SKU. Đơn đã đặt giữ theo bản chụp cũ.");return "redirect:/quan-tri/model/"+model+"/sku/"+sku+"/thuoc-tinh";}catch(IllegalArgumentException ex){m.addAttribute("loi",ex.getMessage());}return suaGiaTri(model,sku,attribute,u,m);}
    @PostMapping("/model/{model}/sku/{sku}/thuoc-tinh/{attribute}/xoa") public String xoaGiaTri(@PathVariable long model,@PathVariable long sku,@PathVariable long attribute,Principal u,RedirectAttributes flash){service.xoaGiaTri(u.getName(),model,sku,attribute);flash.addFlashAttribute("thongBao","Đã bỏ giá trị thuộc tính khỏi SKU; bản chụp đơn cũ giữ nguyên.");return "redirect:/quan-tri/model/"+model+"/sku/"+sku+"/thuoc-tinh";}
    private long number(Map<String,Object> row,String key){return ((Number)row.get(key)).longValue();}
}
